<script setup>
import { computed,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { downloadCSV,printReport } from '../../lib/exports.js'
const store=useDemo(),route=useRoute(),router=useRouter(),q=useQuasar(),policyMode=computed(()=>route.path==='/admin/policy')
const form=ref(false),vesselId=ref(''),eventId=ref(''),age=ref(null),prior=ref(null),defects=ref(null),critical=ref('unknown'),notes=ref(''),error=ref('')
const assessments=computed(()=>store.visibleRecords('assessments'))
const detail=computed(()=>assessments.value.find(a=>a.id===route.params.id&&(!a.eventId||store.getEvent(a.eventId))))
const result=computed(()=>{
 const values=[age.value,prior.value,defects.value],unknown=values.some(x=>x==null||x==='')||critical.value==='unknown',hardStop=critical.value==='yes'
 const number=x=>x==null||x===''?null:Number(x),a=number(age.value),p=number(prior.value),d=number(defects.value)
 const score=unknown?null:(a>=20?2:a>=10?1:0)+Math.min(p,3)*2+Math.min(d,3)*2
 return {score,band:hardStop?'Critical review':unknown?'Unassessed':score>=8?'Elevated review':score>=4?'Routine review':'Baseline',manualReview:unknown||hardStop||score>=8,hardStop}
})
function start(){form.value=true;error.value=''}
function save(){
 error.value='';if(!vesselId.value){error.value='Select a fictional vessel.';return}
 if([age.value,prior.value,defects.value].some(x=>x!==null&&x!==''&&(!Number.isFinite(Number(x))||Number(x)<0||!Number.isInteger(Number(x))))){error.value='Known age, involvement and defect counts must be nonnegative whole numbers. Leave unknown values empty.';return}
 try {const normalize=x=>x===null||x===''?null:Number(x);const record=store.add('assessments',{vesselId:vesselId.value,eventId:eventId.value||null,methodology:'Prototype rules v1',inputs:{age:normalize(age.value),priorInvolvements:normalize(prior.value),unresolvedDefects:normalize(defects.value),criticalCondition:critical.value,notes:notes.value},...result.value,createdBy:store.currentUser.value.id,createdAt:new Date().toISOString()});form.value=false;router.push(`/admin/risk/${record.id}`);q.notify({type:'positive',message:'Prototype assessment saved with inputs and methodology.'})}catch(e){error.value=e.message}
}
const allEvents=computed(()=>store.visibleEvents.value)
const policyEvidence=computed(()=>[
 {id:'position',title:'Improve position evidence coverage',count:allEvents.value.filter(e=>e.positionQuality==='unknown'||e.lat==null||e.lon==null).length,denominator:allEvents.value.length,unit:'events without usable coordinates',link:'/admin/locations',priority:'High',recommendation:'Request source coordinates and record accuracy before approving a map position.'},
 {id:'unknowns',title:'Confirm casualty knowledge',count:allEvents.value.filter(e=>e.consequences?.fatalities==null).length,denominator:allEvents.value.length,unit:'events with unknown fatality counts',link:'/admin/analytics',priority:'High',recommendation:'Distinguish an observed zero from missing information; reconcile the latest event observation.'},
 {id:'actions',title:'Follow up outstanding recommendations',count:store.state.actions.filter(a=>a.status!=='completed'&&allEvents.value.some(e=>e.id===a.eventId)).length,denominator:store.state.actions.filter(a=>allEvents.value.some(e=>e.id===a.eventId)).length,unit:'open or in-progress actions',link:'/admin/actions',priority:'Medium',recommendation:'Assign an owner and due date; retain outcome evidence and completion history.'},
 {id:'lineage',title:'Complete source lineage',count:allEvents.value.filter(e=>!e.sourceLineage?.row).length,denominator:allEvents.value.length,unit:'events without a source row',link:'/admin/reconciliation',priority:'Medium',recommendation:'Record source reference, row and accepted grouping before reconciling annual tables.'}
])
const edit=ref(false),editing=ref(null),policyTitle=ref(''),evidence=ref(''),priority=ref('Medium'),status=ref('proposed'),ownerId=ref(''),policyNotes=ref('')
function openPolicy(item){editing.value=item || null;policyTitle.value=item?.title || '';evidence.value=item?.evidence || '';priority.value=item?.priority || 'Medium';status.value=item?.status || 'proposed';ownerId.value=item?.ownerId || store.currentUser.value.id;policyNotes.value=item?.notes || '';edit.value=true}
function savePolicy(){if(!policyTitle.value.trim()||!evidence.value.trim()){q.notify({type:'negative',message:'Provide a recommendation title and evidence reference.'});return}try{const data={title:policyTitle.value,evidence:evidence.value,priority:priority.value,status:status.value,ownerId:ownerId.value,notes:policyNotes.value};editing.value?store.update('policyItems',editing.value.id,data):store.add('policyItems',data);edit.value=false;q.notify({type:'positive',message:'Evidence-linked recommendation saved.'})}catch(e){q.notify({type:'negative',message:e.message})}}
function printAssessment(){printReport({title:'Prototype risk assessment',subtitle:'Proposed rules v1 · not a validated predictive model',metadata:{ID:detail.value.id,Methodology:detail.value.methodology,Created:detail.value.createdAt},rows:[{Vessel:store.state.vessels.find(v=>v.id===detail.value.vesselId)?.name || detail.value.vesselId,...detail.value.inputs,Score:detail.value.score,Band:detail.value.band,'Manual review':detail.value.manualReview,'Hard stop':detail.value.hardStop}],sections:[{title:'Method',content:'Age below 10 = 0; 10–19 = 1; 20+ = 2. Prior involvements and unresolved defects each contribute 2 points per count, capped at 3 per input. Any unknown input makes score Unknown. Critical condition requires review regardless of score. No MARINA approval or predictive validity is asserted.'}]})}
</script>
<template>
 <div class="page-wrap">
 <PageHeader :title="policyMode?'Policy review':detail?'Assessment detail':'Risk assessments'" :subtitle="policyMode?'Evidence-linked recommendations use current fictional observations and explicit coverage.':'A proposed, versioned indicator demonstration. Unknown values, observed zero and hard-stop review remain distinct.'" :eyebrow="policyMode?'EVIDENCE AND FOLLOW-UP':'PROTOTYPE METHODOLOGY'"><template #actions><q-btn v-if="policyMode" color="primary" no-caps icon="add" label="Add recommendation" @click="openPolicy()" /><q-btn v-else-if="!detail" color="primary" no-caps icon="add" label="New assessment" @click="start" /><template v-else><q-btn no-caps outline label="Assessment register" to="/admin/risk" /><q-btn v-if="store.can('export')" no-caps color="primary" icon="print" label="Print assessment" @click="printAssessment" /></template></template></PageHeader>
 <q-banner rounded class="bg-amber-1 text-dark q-mb-lg"><template #avatar><q-icon name="science" /></template>{{policyMode?'These counts describe data coverage and open work. They do not establish causal effects, policy effectiveness or fixed statistical claims.':'Prototype rules v1 has no asserted MARINA approval or predictive validation. Operational decisions require an authorized human assessment.'}}</q-banner>
 <template v-if="policyMode"><div class="policy-grid"><div v-for="item in policyEvidence" :key="item.id" class="panel"><div class="row justify-between"><h2 class="section-title">{{item.title}}</h2><q-chip dense :color="item.priority==='High'?'amber-2':'blue-1'" text-color="dark">{{item.priority}}</q-chip></div><div class="metric-value">{{item.count}} <span class="text-body1 muted">/ {{item.denominator}}</span></div><p class="muted">{{item.unit}}</p><p>{{item.recommendation}}</p><q-btn flat no-caps color="primary" icon-right="arrow_forward" label="Inspect underlying evidence" :to="item.link" /><q-btn flat no-caps color="primary" label="Track recommendation" @click="openPolicy({title:item.title,evidence:`${item.count} / ${item.denominator} ${item.unit}; current scoped fictional dataset`,priority:item.priority,notes:item.recommendation})" /></div></div><div class="panel q-mt-lg"><div class="row justify-between items-center"><h2 class="section-title">Recommendation register</h2><q-btn v-if="store.can('export')" no-caps outline icon="download" label="Export register" @click="downloadCSV('policy-recommendations.csv',store.state.policyItems)" /></div><q-table flat :rows="store.state.policyItems" :columns="[{name:'title',label:'Recommendation',field:'title',align:'left'},{name:'evidence',label:'Evidence / coverage',field:'evidence',align:'left'},{name:'priority',label:'Priority',field:'priority'},{name:'status',label:'Status',field:'status'},{name:'owner',label:'Owner',field:r=>store.state.users.find(u=>u.id===r.ownerId)?.name || 'Unassigned'},{name:'edit',label:'Action',field:'id'}]" row-key="id" wrap-cells><template #body-cell-edit="props"><q-td :props="props"><q-btn flat no-caps color="primary" label="Review / update" @click="openPolicy(props.row)" /></q-td></template></q-table><p class="muted">Coverage uses all currently authorized events, independent of the analytics filter. Counts are live observations; a saved recommendation preserves its stated evidence text.</p></div></template>
 <template v-else-if="detail"><div class="metric-grid q-mb-lg"><div class="metric-card"><div class="metric-value">{{detail.score ?? 'Unknown'}}</div>Prototype score</div><div class="metric-card"><div class="text-h5">{{detail.band}}</div>Review band</div><div class="metric-card"><div class="text-h5">{{detail.manualReview?'Required':'No trigger'}}</div>Manual review</div><div class="metric-card"><div class="text-h5">{{detail.hardStop?'Active':'No trigger'}}</div>Critical condition</div></div><div class="panel"><h2 class="section-title">Retained inputs</h2><p>Vessel: {{store.state.vessels.find(v=>v.id===detail.vesselId)?.name || detail.vesselId}} · {{detail.methodology}} · {{detail.createdAt}}</p><q-list separator><q-item v-for="(value,key) in detail.inputs" :key="key"><q-item-section>{{key}}</q-item-section><q-item-section side>{{value ?? 'Unknown'}}</q-item-section></q-item></q-list><p class="muted q-mt-lg">An assessment with any unknown rule input has no numerical score. A known zero means the observer explicitly entered zero. The saved inputs and version remain attached to this assessment.</p></div></template>
 <template v-else-if="route.params.id"><div class="panel">Assessment unavailable in your current account scope. <router-link to="/admin/risk">Return to register</router-link>.</div></template>
 <div v-else class="panel"><q-table flat :rows="assessments" :columns="[{name:'vessel',label:'Vessel',field:a=>store.state.vessels.find(v=>v.id===a.vesselId)?.name || a.vesselId,align:'left'},{name:'methodology',label:'Version',field:'methodology'},{name:'score',label:'Score',field:a=>a.score??'Unknown'},{name:'band',label:'Review band',field:'band'},{name:'manualReview',label:'Manual review',field:a=>a.manualReview?'Required':'No trigger'},{name:'createdAt',label:'Saved',field:'createdAt'},{name:'open',label:'Details',field:'id'}]" row-key="id"><template #body-cell-open="props"><q-td :props="props"><q-btn no-caps flat color="primary" label="Open assessment" :to="`/admin/risk/${props.row.id}`" /></q-td></template><template #no-data><div class="q-pa-lg full-width">No saved assessments. Start a versioned prototype assessment to compare zero and unknown inputs.</div></template></q-table><q-expansion-item label="Read Prototype rules v1" icon="rule" class="q-mt-lg"><div class="q-pa-md"><p>Age: below 10 years = 0; 10–19 = 1; 20+ = 2. Prior involvements: 2 × count, capped at three. Unresolved defects: 2 × count, capped at three. Bands: below 4 baseline, 4–7 routine review, 8+ elevated review. Critical condition triggers critical review regardless of score.</p><p>Unknown age, involvement count, defect count or critical condition → score Unknown, Unassessed, manual review. The historical involvement input is supplied by the observer; no unavailable vessel history is inferred.</p></div></q-expansion-item></div>
 <q-dialog v-model="form"><q-card style="width:720px;max-width:95vw"><q-card-section><h2 class="section-title">New prototype assessment</h2><div class="form-grid"><q-select v-model="vesselId" outlined emit-value map-options :options="store.state.vessels.map(v=>({label:v.name,value:v.id}))" label="Fictional vessel" /><q-select v-model="eventId" outlined emit-value map-options clearable :options="allEvents.map(e=>({label:e.ref,value:e.id}))" label="Related event (optional)" /><q-input v-model="age" outlined type="number" min="0" label="Age in whole years (empty = unknown)" /><q-input v-model="prior" outlined type="number" min="0" label="Prior involvements (empty = unknown)" /><q-input v-model="defects" outlined type="number" min="0" label="Unresolved defects (empty = unknown)" /><q-select v-model="critical" outlined :options="['unknown','no','yes']" label="Critical condition observed" /><q-input v-model="notes" outlined type="textarea" class="span-2" label="Assessment evidence / notes" /></div><div class="q-pa-md bg-blue-1 text-primary rounded-borders q-mt-md">Score {{result.score ?? 'Unknown'}} · {{result.band}} · Manual review {{result.manualReview?'required':'not triggered'}}</div><q-banner v-if="error" class="bg-red-1 text-negative q-mt-md">{{error}}</q-banner></q-card-section><q-card-actions align="right"><q-btn v-close-popup flat no-caps label="Cancel" /><q-btn color="primary" no-caps label="Save assessment" @click="save" /></q-card-actions></q-card></q-dialog>
 <q-dialog v-model="edit"><q-card style="width:680px;max-width:95vw"><q-card-section><h2 class="section-title">{{editing?.id?'Review recommendation':'Add recommendation'}}</h2><div class="form-grid"><q-input v-model="policyTitle" outlined label="Recommendation title" class="span-2" /><q-input v-model="evidence" outlined type="textarea" label="Evidence reference / counts and coverage" class="span-2" /><q-select v-model="priority" outlined :options="['High','Medium','Low']" label="Priority" /><q-select v-model="status" outlined :options="['proposed','under_review','accepted','in_progress','completed','deferred']" label="Review status" /><q-select v-model="ownerId" outlined emit-value map-options :options="store.state.users.map(u=>({label:u.name,value:u.id}))" label="Responsible owner" /><q-input v-model="policyNotes" outlined type="textarea" label="Notes / decision basis" class="span-2" /></div></q-card-section><q-card-actions align="right"><q-btn v-close-popup flat no-caps label="Cancel" /><q-btn color="primary" no-caps label="Save recommendation" @click="savePolicy" /></q-card-actions></q-card></q-dialog>
 </div>
</template>
<style scoped>.policy-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}@media(max-width:650px){.policy-grid{grid-template-columns:1fr}}</style>
